html:
{%- set company_doc = frappe.get_doc('Company', doc.company) if doc.get('company') else None -%}
{%- macro vnd(amount) -%}{{ '{:,.0f}'.format(amount or 0).replace(',', '.') }}{%- endmacro -%}
{%- set d = frappe.utils.getdate(doc.stocktake_date) -%}

<style>
@media print { @page { size: A4 portrait; margin: 20mm 15mm; } }
.st-print a { color: inherit !important; text-decoration: none !important; }
.st-print { font-family: 'Times New Roman', Times, serif; font-size: 13px; line-height: 1.6; max-width: 700px; margin: 0 auto; }
.st-print .header-national { text-align: center; font-weight: bold; text-transform: uppercase; margin-bottom: 5px; }
.st-print .header-motto { text-align: center; font-style: italic; margin-bottom: 20px; }
.st-print h2 { text-align: center; font-size: 16px; font-weight: bold; text-transform: uppercase; margin: 15px 0 5px 0; }
.st-print .sub-title { text-align: center; font-style: italic; margin-bottom: 15px; }
.st-print table { width: 100%; border-collapse: collapse; margin: 10px 0; }
.st-print table th, .st-print table td { border: 1px solid #333; padding: 4px 8px; font-size: 12px; }
.st-print table th { background: #f0f0f0; text-align: center; font-weight: bold; }
.st-print .info-row { margin: 6px 0; }
.st-print .signatures { display: flex; justify-content: space-around; margin-top: 30px; text-align: center; }
.st-print .sign-block { width: 28%; }
.st-print .sign-block .sign-title { font-weight: bold; }
.st-print .sign-block .sign-date { font-style: italic; font-size: 11px; }
.st-print .sign-block .sign-space { height: 50px; }
.st-print .status-mat { color: #c0392b; font-weight: bold; }
.st-print .status-hong { color: #e67e22; font-weight: bold; }
</style>

<div class='st-print'>
  <div class='header-national'>Cộng hòa xã hội chủ nghĩa Việt Nam</div>
  <div class='header-motto'>Độc lập - Tự do - Hạnh phúc</div>

  <h2>BIÊN BẢN KIỂM KÊ {{ 'TÀI SẢN CỐ ĐỊNH' if doc.scope == 'TSCĐ' else 'CCDC' }}</h2>
  <div class='sub-title'>Ngày {{ d.day }} tháng {{ d.month }} năm {{ d.year }}</div>

  <div class='info-row'><b>Số phiếu:</b> {{ doc.name }}</div>
  {%- if company_doc %}
  <div class='info-row'><b>Đơn vị:</b> {{ company_doc.company_name }}</div>
  {%- endif %}
  <div class='info-row'><b>Địa điểm kiểm kê:</b> {{ doc.location or 'Toàn đơn vị' }}</div>
  {%- if doc.department %}
  <div class='info-row'><b>Phòng ban:</b> {{ doc.department }}</div>
  {%- endif %}
  <div class='info-row'><b>Trạng thái:</b> {{ doc.status or 'Draft' }}</div>

  <table style='margin-top:15px'>
    <thead>
      <tr>
        <th style='width:5%'>STT</th>
        <th style='width:35%'>Tên tài sản/CCDC</th>
        <th style='width:15%'>Mã số</th>
        <th style='width:20%'>Giá trị sổ sách (VNĐ)</th>
        <th style='width:15%'>Tình trạng</th>
        <th style='width:10%'>Ghi chú</th>
      </tr>
    </thead>
    <tbody>
      {%- for item in doc.stocktake_items or [] %}
      <tr>
        <td style='text-align:center'>{{ loop.index }}</td>
        <td>{{ item.target_name }}</td>
        <td style='text-align:center'>{{ item.target_name }}</td>
        <td style='text-align:right'>{{ vnd(item.book_value) }}</td>
        <td style='text-align:center' class='{{ "status-mat" if item.physical_status == "Mất" else ("status-hong" if item.physical_status == "Hỏng" else "") }}'>
          {{ item.physical_status or 'Còn nguyên' }}
        </td>
        <td>{{ item.remarks or '' }}</td>
      </tr>
      {%- endfor %}
    </tbody>
  </table>

  {%- if doc.remarks %}
  <div class='info-row' style='margin-top:10px'><b>Ghi chú:</b> {{ doc.remarks }}</div>
  {%- endif %}

  <div class='signatures'>
    <div class='sign-block'>
      <div class='sign-title'>Trưởng đoàn kiểm kê</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
    </div>
    <div class='sign-block'>
      <div class='sign-title'>Thủ kho / Người quản lý</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
    </div>
    <div class='sign-block'>
      <div class='sign-title'>Kế toán tài sản</div>
      <div class='sign-date'>(Ký, họ tên)</div>
      <div class='sign-space'></div>
    </div>
  </div>
</div>
